INSERT INTO `tour_itineraries` VALUES (1, 1, 1, 'Hành trình Cố đô', 'Khám phá Đại Nội Huế và lăng tẩm hoàng cung triều Nguyễn.');
INSERT INTO `tour_itineraries` VALUES (1, 2, 2, 'Hồn Quê Xứ Quảng', 'Tham quan Hội An cổ kính và trải nghiệm cày cấy làng Trà Quế.');
INSERT INTO `tour_itineraries` VALUES (1, 3, 3, 'Hồn Đất Văn Lâm', 'Đi thuyền Vân Long ngắm cảnh sơn thuỷ và xem dệt thêu thủ công.');
INSERT INTO `tour_itineraries` VALUES (1, 4, 4, 'Thiền Giữa Hương Sen', 'Ngắm sen nở mờ sương và tập yoga thiền trên sông nước.');
INSERT INTO `tour_itineraries` VALUES (1, 5, 5, 'Vịnh Xanh Kì Vĩ', 'Tàu sang lướt sóng ngắm hang luồn, hòn trống mái.');
INSERT INTO `tour_itineraries` VALUES (1, 6, 6, 'Sapa Mây Mù', 'Thăm bản H’mông cổ xưa, tìm hiểu nghệ thuật nhuộm chàm.');
INSERT INTO `tour_itineraries` VALUES (1, 7, 7, 'Khám Phá Rừng Xanh', 'Đi bộ xuyên rừng ngắm bằng lăng cổ thụ kì vĩ.');
INSERT INTO `tour_itineraries` VALUES (1, 8, 8, 'Cát Vàng Mũi Né', 'Ngắm bình minh cồn cát trắng, tham quan Suối Tiên.');
INSERT INTO `tour_itineraries` VALUES (1, 9, 9, 'Đại Dương Phú Quốc', 'Lặn cano 4 đảo nhỏ hoang sơ hoà vào san hô rực rỡ.');
INSERT INTO `tour_itineraries` VALUES (1, 10, 10, 'Sông Nước Cần Thơ', 'Ăn sáng hủ tiếu chợ nổi Cái Răng sôi động.');
INSERT INTO `tour_itinerary_details` VALUES ('11:30:00', '08:00:00', 1, 1, 1, NULL, 'Tham quan Đại Nội', 'Chiêm ngưỡng Ngọ Môn, Điện Thái Hoà và nghe thuyết minh hoàng triều.');
INSERT INTO `tour_itinerary_details` VALUES ('12:00:00', '09:00:00', 2, 2, 2, 'Lunch', 'Dạo bước phố cổ', 'Thăm Chùa Cầu, hội quán Quảng Đông lấp lánh đèn lồng.');
INSERT INTO `tour_itinerary_details` VALUES ('17:00:00', '14:00:00', 3, 3, 3, NULL, 'Du thuyền Vân Long', 'Đi thuyền nan ngắm đàn voọc quần đùi trắng chuyền cành vách đá.');
INSERT INTO `tour_itinerary_details` VALUES ('08:30:00', '06:00:00', 4, 4, 4, 'Breakfast', 'Thiền hành đón nắng', 'Tập yoga tĩnh tâm trên nhà chòi gỗ giữa đầm sen lộng gió.');
INSERT INTO `tour_itinerary_details` VALUES ('11:30:00', '08:30:00', 5, 5, 5, NULL, 'Khám phá hang động', 'Tham quan động Thiên Cung hoành tráng thạch nhũ kì vĩ.');
INSERT INTO `tour_itinerary_details` VALUES ('12:00:00', '09:00:00', 6, 6, 6, 'Lunch', 'Thăm bản Cát Cát', 'Đi bộ ngắm cối xay nước khổng lồ và check-in thác Tiên Sa.');
INSERT INTO `tour_itinerary_details` VALUES ('15:00:00', '08:00:00', 7, 7, 7, 'Lunch', 'Trekking Bàu Sấu', 'Đi bộ 5km xuyên rừng rậm Nam Cát Tiên đến đầm lầy bảo tồn.');
INSERT INTO `tour_itinerary_details` VALUES ('08:30:00', '05:30:00', 8, 8, 8, NULL, 'Đón bình minh cồn cát', 'Trượt cát đồi cát trắng bằng máng trượt và mô tô ATV chạy địa hình.');
INSERT INTO `tour_itinerary_details` VALUES ('15:00:00', '09:00:00', 9, 9, 9, 'Lunch', 'Lặn ngắm san hô', 'Tắm biển Hòn Thơm lặn biển ống thở ngắm rạn san hô tự nhiên đẹp nhất Phú Quốc.');
INSERT INTO `tour_itinerary_details` VALUES ('08:30:00', '06:00:00', 10, 10, 10, 'Breakfast', 'Chợ nổi Cái Răng', 'Lên thuyền ngắm chợ nổi nhộn nhịp, ăn hủ tiếu nóng hổi chòng chành trên sông.');
INSERT INTO `tour_locations` VALUES (1, 16.46780000, 107.57890000, 1, 'Đại Nội Huế', 'Hoàng cung triều Nguyễn cổ kính, uy nghiêm.');
INSERT INTO `tour_locations` VALUES (1, 15.88010000, 108.33800000, 2, 'Phố cổ Hội An', 'Di sản văn hoá thế giới thương cảng đèn lồng rực rỡ.');
INSERT INTO `tour_locations` VALUES (1, 20.36210000, 105.90870000, 3, 'Đầm Vân Long', 'Khu bảo tồn thiên nhiên ngập nước lớn nhất vịnh Bắc Bộ.');
INSERT INTO `tour_locations` VALUES (1, 10.45000000, 105.70000000, 4, 'Đồng Tháp Mười', 'Xứ sở sen hồng ngào ngạt ngút ngàn tầm mắt.');
INSERT INTO `tour_locations` VALUES (1, 20.86540000, 107.08120000, 5, 'Đảo Ti Tốp Hạ Long', 'Bãi tắm cát trắng tuyệt đẹp tựa lưng vách đá.');
INSERT INTO `tour_locations` VALUES (1, 22.32890000, 103.84150000, 6, 'Bản Cát Cát Sapa', 'Bản làng mộc mạc bên thác nước mát rượi.');
INSERT INTO `tour_locations` VALUES (1, 11.45890000, 107.36540000, 7, 'Bàu Sấu Cát Tiên', 'Vùng đầm lầy bảo tồn cá sấu tự nhiên quý hiếm.');
INSERT INTO `tour_locations` VALUES (1, 10.95000000, 108.28000000, 8, 'Đồi Cát Trắng Mũi Né', 'Tiểu sa mạc cát mênh mông lấp lánh ánh vàng.');
INSERT INTO `tour_locations` VALUES (1, 9.95430000, 104.01520000, 9, 'Hòn Thơm Phú Quốc', 'Thiên đường đảo ngọc cát trắng nước trong vắt.');
INSERT INTO `tour_locations` VALUES (1, 9.99890000, 105.74890000, 10, 'Chợ nổi Cái Răng', 'Chợ đầu mối mua bán trái cây sầm uất trên sông.');
