INSERT INTO `tours` VALUES (5000000.00, 1, 20, '2026-06-22T08:22:21', 1, NULL, 'Hành trình di sản cố đô Huế trải nghiệm văn hoá ẩm thực cung đình Huế.', '12 Giờ', 'Tìm về hơi ấm vẹn nguyên của lòng biết ơn và sự gắn kết.', 'Đoàn tụ - Huế', 'doantu');
INSERT INTO `tours` VALUES (7000000.00, 1, 15, '2026-06-22T08:22:21', 2, NULL, 'Tham quan phố cổ Hội An, làng rau Trà Quế và làng gốm Thanh Hà.', '6 Giờ', 'Lắng nghe nhịp điệu mộc mạc của đất mẹ và hồn quê xứ Quảng.', 'Tinh túy đồng nội - Quảng Nam', 'dongnoi');
INSERT INTO `tours` VALUES (5000000.00, 1, 15, '2026-06-22T08:22:21', 3, NULL, 'Khám phá đầm Vân Long và làng nghề thêu ren truyền thống Văn Lâm.', '5 Giờ', 'Chạm vào hồn cốt của thời gian qua những tạo tác từ đôi bàn tay nghệ nhân.', 'Di sản thủ công - Ninh Bình', 'disan');
INSERT INTO `tours` VALUES (7000000.00, 1, 10, '2026-06-22T08:22:21', 4, NULL, 'Đi xuồng ba lá ngắm sen nở rộ Đồng Tháp Mười thiền định thư thái.', '10 Giờ', 'Sự thanh lọc thuần khiết cho thân - tâm - trí giữa vùng sông nước mờ sương.', 'Tĩnh lặng liên hoa - Tháp Mười', 'tinhlang');
INSERT INTO `tours` VALUES (1000000.00, 1, 30, '2026-06-22T08:22:21', 5, NULL, 'Lướt sóng vịnh Bắc Bộ ngắm động Thiên Cung hoành tráng.', '4 Giờ', 'Du thuyền sang trọng ngắm kỳ quan thiên nhiên thế giới.', 'Huyền thoại vịnh xanh - Hạ Long', 'Half-Day');
INSERT INTO `tours` VALUES (1300000.00, 1, 20, '2026-06-22T08:22:21', 6, NULL, 'Leo ruộng bậc thang bản Cát Cát trải nghiệm văn hoá đồng bào H’mông.', '8 Giờ', 'Gặp gỡ nụ cười hồn hậu vùng cao mây phủ.', 'Bình yên bản nhỏ - Sapa', 'Full-Day');
INSERT INTO `tours` VALUES (2200000.00, 1, 12, '2026-06-22T08:22:21', 7, NULL, 'Xem thú ban đêm rừng Nam Cát Tiên ngắm chim muông kì thú.', '14 Giờ', 'Lắng nghe tiếng gọi rừng xanh thẳm huyền bí.', 'Nhịp đập hoang dã - Cát Tiên', 'Full-Day');
INSERT INTO `tours` VALUES (900000.00, 1, 15, '2026-06-22T08:22:21', 8, NULL, 'Khám phá Đồi Cát Trắng, Đồi Cát Đỏ Mũi Né bằng xe địa hình ATV.', '5 Giờ', 'Trượt cát đón mặt trời mọc rực rỡ.', 'Bình minh cồn cát - Mũi Né', 'Half-Day');
INSERT INTO `tours` VALUES (1400000.00, 1, 25, '2026-06-22T08:22:21', 9, NULL, 'Lặn cano 4 đảo ngắm san hô thiên nhiên rực rỡ Phú Quốc.', '6 Giờ', 'Hoà mình vào làn nước xanh lục bảo óng ánh.', 'Sóng hát san hô - Phú Quốc', 'Half-Day');
INSERT INTO `tours` VALUES (800000.00, 1, 20, '2026-06-22T08:22:21', 10, NULL, 'Đi chợ nổi Cái Răng thưởng thức bữa sáng trên ghe thuyền mộc mạc.', '5 Giờ', 'Ngọt lịm trái chín trĩu cành miền Tây sông nước.', 'Hương sắc miệt vườn - Cần Thơ', 'Half-Day');
